package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {

    // Event type constants
    public static final int SUBMIT = 0;
    public static final int SCHEDULE = 1;
    public static final int EVICT = 2;
    public static final int FAIL = 3;
    public static final int FINISH = 4;
    public static final int KILL = 5;
    public static final int LOST = 6;
    public static final int UPDATE_PENDING = 7;
    public static final int UPDATE_RUNNING = 8;

    // Fields according to schema
    private long timestamp;          // microseconds
    private String missingInfo;
    private long jobId;
    private int taskIndex;
    private Long machineId;          // can be null
    private int eventType;
    private String userName;
    private int schedulingClass;
    private int priority;
    private double cpuRequest;
    private double memoryRequest;
    private double diskSpaceRequest;
    private int differentMachineConstraint;

    public TaskEvent() {}

    public TaskEvent(long timestamp, String missingInfo, long jobId, int taskIndex,
                     Long machineId, int eventType, String userName, int schedulingClass,
                     int priority, double cpuRequest, double memoryRequest,
                     double diskSpaceRequest, int differentMachineConstraint) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
        this.userName = userName;
        this.schedulingClass = schedulingClass;
        this.priority = priority;
        this.cpuRequest = cpuRequest;
        this.memoryRequest = memoryRequest;
        this.diskSpaceRequest = diskSpaceRequest;
        this.differentMachineConstraint = differentMachineConstraint;
    }

    public static TaskEvent fromString(String line) {
        String[] parts = line.split(",", -1);
        if (parts.length < 13) {
            return null;
        }

        try {
            long timestamp = parts[0].isEmpty() ? 0L : Long.parseLong(parts[0]);
            String missingInfo = parts[1];
            long jobId = parts[2].isEmpty() ? 0L : Long.parseLong(parts[2]);
            int taskIndex = parts[3].isEmpty() ? 0 : Integer.parseInt(parts[3]);
            Long machineId = parts[4].isEmpty() ? null : Long.parseLong(parts[4]);
            int eventType = parts[5].isEmpty() ? -1 : Integer.parseInt(parts[5]);
            String userName = parts[6];
            int schedulingClass = parts[7].isEmpty() ? 0 : Integer.parseInt(parts[7]);
            int priority = parts[8].isEmpty() ? 0 : Integer.parseInt(parts[8]);
            double cpuRequest = parts[9].isEmpty() ? 0.0 : Double.parseDouble(parts[9]);
            double memoryRequest = parts[10].isEmpty() ? 0.0 : Double.parseDouble(parts[10]);
            double diskSpaceRequest = parts[11].isEmpty() ? 0.0 : Double.parseDouble(parts[11]);
            int differentMachineConstraint = parts[12].isEmpty() ? 0 : Integer.parseInt(parts[12]);

            return new TaskEvent(timestamp, missingInfo, jobId, taskIndex, machineId,
                    eventType, userName, schedulingClass, priority, cpuRequest,
                    memoryRequest, diskSpaceRequest, differentMachineConstraint);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    // Getters
    public long getTimestamp() { return timestamp; }
    public String getMissingInfo() { return missingInfo; }
    public long getJobId() { return jobId; }
    public int getTaskIndex() { return taskIndex; }
    public Long getMachineId() { return machineId; }
    public int getEventType() { return eventType; }
    public String getUserName() { return userName; }
    public int getSchedulingClass() { return schedulingClass; }
    public int getPriority() { return priority; }
    public double getCpuRequest() { return cpuRequest; }
    public double getMemoryRequest() { return memoryRequest; }
    public double getDiskSpaceRequest() { return diskSpaceRequest; }
    public int getDifferentMachineConstraint() { return differentMachineConstraint; }

    // Setters
    public void setTimestamp(long timestamp) { this.timestamp = timestamp; }
    public void setMissingInfo(String missingInfo) { this.missingInfo = missingInfo; }
    public void setJobId(long jobId) { this.jobId = jobId; }
    public void setTaskIndex(int taskIndex) { this.taskIndex = taskIndex; }
    public void setMachineId(Long machineId) { this.machineId = machineId; }
    public void setEventType(int eventType) { this.eventType = eventType; }
    public void setUserName(String userName) { this.userName = userName; }
    public void setSchedulingClass(int schedulingClass) { this.schedulingClass = schedulingClass; }
    public void setPriority(int priority) { this.priority = priority; }
    public void setCpuRequest(double cpuRequest) { this.cpuRequest = cpuRequest; }
    public void setMemoryRequest(double memoryRequest) { this.memoryRequest = memoryRequest; }
    public void setDiskSpaceRequest(double diskSpaceRequest) { this.diskSpaceRequest = diskSpaceRequest; }
    public void setDifferentMachineConstraint(int differentMachineConstraint) { this.differentMachineConstraint = differentMachineConstraint; }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", taskIndex=" + taskIndex +
                ", eventType=" + eventType +
                '}';
    }
}

