    public static class FinishedJobFilter implements CoFlatMapFunction<Tuple2<Long, Long>, Long, String> {
        private Map<Long, Long> stageCounts = new HashMap<>();
        private Map<Long, Boolean> finishedJobs = new HashMap<>();

