package clusterdata.datatypes;

import java.io.Serializable;

public class JobEvent implements Serializable {

    // Event type constants
    public static final int SUBMIT = 0;
    public static final int SCHEDULE = 1;
    public static final int EVICT = 2;
    public static final int FAIL = 3;
    public static final int FINISH = 4;
    public static final int KILL = 5;
    public static final int LOST = 6;
    public static final int UPDATE_PENDING = 7;
    public static final int UPDATE_RUNNING = 8;

    // Fields according to schema
    private long timestamp;          // microseconds
    private String missingInfo;
    private long jobId;
    private int eventType;
    private String userName;
    private int schedulingClass;
    private String jobName;
    private String logicalJobName;

    public JobEvent() {}

    public JobEvent(long timestamp, String missingInfo, long jobId, int eventType,
                    String userName, int schedulingClass, String jobName, String logicalJobName) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.eventType = eventType;
        this.userName = userName;
        this.schedulingClass = schedulingClass;
        this.jobName = jobName;
        this.logicalJobName = logicalJobName;
    }

    public static JobEvent fromString(String line) {
        String[] parts = line.split(",", -1);
        if (parts.length < 8) {
            return null;
        }

        try {
            long timestamp = parts[0].isEmpty() ? 0L : Long.parseLong(parts[0]);
            String missingInfo = parts[1];
            long jobId = parts[2].isEmpty() ? 0L : Long.parseLong(parts[2]);
            int eventType = parts[3].isEmpty() ? -1 : Integer.parseInt(parts[3]);
            String userName = parts[4];
            int schedulingClass = parts[5].isEmpty() ? 0 : Integer.parseInt(parts[5]);
            String jobName = parts[6];
            String logicalJobName = parts[7];

            return new JobEvent(timestamp, missingInfo, jobId, eventType,
                    userName, schedulingClass, jobName, logicalJobName);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    public boolean isFinished() {
        return eventType == FINISH || eventType == FAIL || eventType == KILL || eventType == LOST;
    }

    // Getters
    public long getTimestamp() { return timestamp; }
    public String getMissingInfo() { return missingInfo; }
    public long getJobId() { return jobId; }
    public int getEventType() { return eventType; }
    public String getUserName() { return userName; }
    public int getSchedulingClass() { return schedulingClass; }
    public String getJobName() { return jobName; }
    public String getLogicalJobName() { return logicalJobName; }

    // Setters
    public void setTimestamp(long timestamp) { this.timestamp = timestamp; }
    public void setMissingInfo(String missingInfo) { this.missingInfo = missingInfo; }
    public void setJobId(long jobId) { this.jobId = jobId; }
    public void setEventType(int eventType) { this.eventType = eventType; }
    public void setUserName(String userName) { this.userName = userName; }
    public void setSchedulingClass(int schedulingClass) { this.schedulingClass = schedulingClass; }
    public void setJobName(String jobName) { this.jobName = jobName; }
    public void setLogicalJobName(String logicalJobName) { this.logicalJobName = logicalJobName; }

    @Override
    public String toString() {
        return "JobEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", eventType=" + eventType +
                '}';
    }
}
